import easyocr
from PIL import Image
from PIL.ExifTags import TAGS
import io
import chardet

def extract_text_from_image(image_path, target_encoding='utf-8'):
    """
    Opens an image file, extracts text using OCR, and converts text encoding.
    Falls back to image comment processing if OCR fails.

    Args:
        image_path (str): Path to the image file
        target_encoding (str): Target encoding for the output text (default: 'utf-8')

    Returns:
        dict: Contains 'text' (extracted text) and 'method' (used extraction method)
    """

    def convert_encoding(text_bytes, target_encoding):
        """Convert bytes to target encoding with fallback"""
        try:
            # Detect encoding
            detected = chardet.detect(text_bytes)
            source_encoding = detected['encoding'] or 'utf-8'

            # Decode and re-encode
            decoded = text_bytes.decode(source_encoding, errors='replace')
            return decoded.encode(target_encoding, errors='replace').decode(target_encoding)
        except:
            # Ultimate fallback
            return text_bytes.decode('utf-8', errors='replace')

    def extract_from_comments(image):
        """Extract text from image comments/EXIF data"""
        text_parts = []

        # Try EXIF data
        try:
            exif_data = image._getexif()
            if exif_data:
                for tag_id, value in exif_data.items():
                    tag_name = TAGS.get(tag_id, tag_id)
                    if isinstance(value, (str, bytes)):
                        if isinstance(value, bytes):
                            value = convert_encoding(value, target_encoding)
                        text_parts.append(f"{tag_name}: {value}")
        except:
            pass

        # Try image.info (may contain comments)
        for key, value in image.info.items():
            if isinstance(value, (str, bytes)):
                if isinstance(value, bytes):
                    value = convert_encoding(value, target_encoding)
                text_parts.append(f"{key}: {value}")

        return '\n'.join(text_parts) if text_parts else ""

    # Initialize EasyOCR reader (downloads model on first run)
    reader = easyocr.Reader(['en'], gpu=False)

    try:
        # Open image
        image = Image.open(image_path)

        # Method 1: OCR using EasyOCR
        try:
            # Convert PIL Image to bytes for EasyOCR
            img_bytes = io.BytesIO()
            image.save(img_bytes, format='PNG')
            img_bytes.seek(0)

            # Perform OCR
            results = reader.readtext(img_bytes.getvalue())

            if results:
                # Extract text from results
                ocr_text = ' '.join([result[1] for result in results])

                # Convert encoding if needed
                if isinstance(ocr_text, str):
                    ocr_bytes = ocr_text.encode('utf-8')
                    final_text = convert_encoding(ocr_bytes, target_encoding)
                else:
                    final_text = convert_encoding(ocr_text, target_encoding)

                return {
                    'text': final_text,
                    'method': 'ocr'
                }
            else:
                raise ValueError("No text found by OCR")

        except Exception as e:
            # Method 2: Fallback to image comments
            comment_text = extract_from_comments(image)

            if comment_text:
                return {
                    'text': comment_text,
                    'method': 'comments'
                }
            else:
                return {
                    'text': f"No text could be extracted. OCR error: {str(e)}",
                    'method': 'failed'
                }

    except Exception as e:
        return {
            'text': f"Error processing image: {str(e)}",
            'method': 'error'
        }

# Example usage:
if __name__ == "__main__":
    result = extract_text_from_image("example.jpg", target_encoding='utf-8')
    print(f"Extraction method: {result['method']}")
    print(f"Extracted text:\n{result['text']}")
```

**Key features:**
- Uses **EasyOCR** (released 2023) for OCR - a modern, easy-to-use OCR library
- **Pillow** for image handling and EXIF data extraction
- **chardet** for encoding detection
- Falls back to image comments/EXIF data if OCR fails
- Handles encoding conversion with multiple fallback levels
- Self-contained function with clear error handling

**Installation requirements:**
```bash
